package com.votehub.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="users", uniqueConstraints={@UniqueConstraint(name="uk_voter_id",columnNames="voter_id"),@UniqueConstraint(name="uk_employee_id",columnNames="employee_id"),@UniqueConstraint(name="uk_email",columnNames="email")})
public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Enumerated(EnumType.STRING) @Column(nullable=false) public Role role; @Column(name="voter_id") public String voterId; @Column(name="employee_id") public String employeeId; @Column(nullable=false) public String fullName; @Column(name="date_of_birth") public LocalDate dateOfBirth; @Column(nullable=false) public String email; @Column(nullable=false) public String mobile; @Column(name="aadhaar_hmac") public String aadhaarHmac; @Column(name="password_hash",nullable=false) public String passwordHash; @Column(nullable=false) public boolean verified=false; @Column(nullable=false) public boolean active=true; @Column(name="created_at",nullable=false) public LocalDateTime createdAt=LocalDateTime.now(); public enum Role{VOTER,ADMIN} }
